+++ b/source/core/utils/proxy-events.ts
@@ -3,12 +3,15 @@ import type {EventEmitter} from 'node:events';
 type AnyFunction = (...arguments_: unknown[]) => void;
 type Functions = Record<string, AnyFunction>;

-export default function proxyEvents(from: EventEmitter, to: EventEmitter, events: Readonly<string[]>): () => void {
+export default function proxyEvents(from: EventEmitter, to: EventEmitter, events: Readonly<string[]>, onClose?: () => void): () => void {
 	const eventFunctions: Functions = {};
+	const state = {active: true};

 	for (const event of events) {
 		const eventFunction = (...arguments_: unknown[]) => {
-			to.emit(event, ...arguments_);
+			if (state.active) {
+				to.emit(event, ...arguments_);
+			}
 		};

 		eventFunctions[event] = eventFunction;
@@ -17,8 +20,16 @@ export default function proxyEvents(from: EventEmitter, to: EventEmitter, events
 	}

 	return () => {
+		if (!state.active) {
+			return;
+		}
+
+		state.active = false;
+
 		for (const [event, eventFunction] of Object.entries(eventFunctions)) {
 			from.off(event, eventFunction);
 		}
+
+		onClose?.();
 	};
 }
