+++ b/source/transfer-relay.ts
@@ -0,0 +1,7 @@
+import type {EventEmitter} from 'node:events';
+import proxyEvents from './core/utils/proxy-events.js';
+
+// Transfer-specific entry point; groundwork: allow-duplicate exposes the fixed event allowlist through the existing proxy
+export function relayTransfer(source: EventEmitter, destination: EventEmitter, onClose: () => void): () => void {
+	return proxyEvents(source, destination, ['uploadProgress', 'downloadProgress', 'error'], onClose);
+}
diff --git a/test/transfer-relay.ts b/test/transfer-relay.ts
new file mode 100644
index 0000000..afc84f6
--- /dev/null
+++ b/test/transfer-relay.ts
@@ -0,0 +1,74 @@
+import {EventEmitter} from 'node:events';
+import test from 'ava';
+import {spy} from 'sinon';
+import {relayTransfer} from '../source/transfer-relay.js';
+
+test('relays only transfer events with their original arguments', t => {
+	const source = new EventEmitter();
+	const destination = new EventEmitter();
+	const onClose = spy();
+	const upload = spy();
+	const download = spy();
+	const failure = spy();
+	const response = spy();
+	const error = new Error('Transfer failed');
+
+	destination.on('uploadProgress', upload);
+	destination.on('downloadProgress', download);
+	destination.on('error', failure);
+	destination.on('response', response);
+
+	const dispose = relayTransfer(source, destination, onClose);
+
+	source.emit('uploadProgress', 1, undefined, 3);
+	source.emit('downloadProgress');
+	source.emit('error', error, 'details');
+	source.emit('response', 200);
+
+	t.true(upload.calledOnceWithExactly(1, undefined, 3));
+	t.true(download.calledOnceWithExactly());
+	t.true(failure.calledOnceWithExactly(error, 'details'));
+	t.is(failure.firstCall.args[0], error);
+	t.false(response.called);
+	t.false(onClose.called);
+
+	dispose();
+	source.emit('uploadProgress', 4);
+
+	t.true(upload.calledOnce);
+	t.true(onClose.calledOnce);
+});
+
+test('disposing before the first event removes only the relay listeners', t => {
+	const source = new EventEmitter();
+	const destination = new EventEmitter();
+	const onClose = spy();
+	const listener = spy();
+
+	source.on('uploadProgress', listener);
+	destination.on('uploadProgress', listener);
+
+	const dispose = relayTransfer(source, destination, onClose);
+	dispose();
+	dispose();
+
+	t.deepEqual(source.eventNames(), ['uploadProgress']);
+	t.deepEqual(source.listeners('uploadProgress'), [listener]);
+	t.deepEqual(destination.listeners('uploadProgress'), [listener]);
+	t.true(onClose.calledOnce);
+});
+
+test('does not forward when an earlier listener disposes the relay during emission', t => {
+	const source = new EventEmitter();
+	const destination = new EventEmitter();
+	const onClose = spy();
+	const upload = spy();
+	destination.on('uploadProgress', upload);
+
+	const dispose = relayTransfer(source, destination, onClose);
+	source.prependListener('uploadProgress', dispose);
+	source.emit('uploadProgress');
+
+	t.false(upload.called);
+	t.true(onClose.calledOnce);
+});
